package cn.kaoyan.assistant;
import android.app.*;import android.content.*;import android.os.Build;import java.util.Calendar;
public class ReminderReceiver extends BroadcastReceiver {
 static void configure(Context c,boolean enabled,int hour,int minute){c.getSharedPreferences("reminder",0).edit().putBoolean("enabled",enabled).putInt("hour",hour).putInt("minute",minute).commit();AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent p=PendingIntent.getBroadcast(c,41,new Intent(c,ReminderReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);a.cancel(p);if(enabled){Calendar t=Calendar.getInstance();t.set(Calendar.HOUR_OF_DAY,hour);t.set(Calendar.MINUTE,minute);t.set(Calendar.SECOND,0);if(t.getTimeInMillis()<=System.currentTimeMillis())t.add(Calendar.DAY_OF_YEAR,1);a.setInexactRepeating(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);}}
 public void onReceive(Context c,Intent i){if(!c.getSharedPreferences("reminder",0).getBoolean("enabled",false))return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("study","每日复习提醒",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent p=PendingIntent.getActivity(c,1,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);n.notify(41,new Notification.Builder(c,"study").setSmallIcon(cn.kaoyan.assistant.R.drawable.ic_launcher).setContentTitle("今天的复习，进展如何？").setContentText("打开研序，查看今日任务并记录完成情况。").setContentIntent(p).setAutoCancel(true).build());}
}
